/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; hits=set()
 for i,l in enumerate(lines):
  if re.search(r'terminat|cancel|without cause',l,re.I):
   hits.update(range(max(0,i-2),min(len(lines),i+5)))
 print('\\nFILE',f.name)
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m[1]
  if i in hits: print(f'{page}: {l}')
PY"

